import React from 'react';
import { List, Skeleton } from 'antd';
import InfiniteScroll from 'react-infinite-scroll-component';
import { useTranslation } from 'react-i18next';
import { Else, If, Then } from 'react-if';
import { ListGridType } from 'antd/es/list';

interface IAppList<T> {
  hasLoadMore?: boolean;
  data: T[];
  grid?: ListGridType;
  layout?: 'vertical' | 'horizontal';
  loadMoreCount?: number;
  renderHeader?: string | React.ReactNode;
  renderFooter?: string | React.ReactNode;
  renderItem: (item: T, index: number) => React.ReactNode;
  renderLoading?: string | React.ReactNode;
  loadMoreData?: () => void;
}

// REFER DOCS https://ant.design/components/list
export const AppList = <D,>({
  hasLoadMore,
  grid,
  data,
  layout = 'horizontal',
  loadMoreCount = 20,
  renderHeader,
  renderFooter,
  renderItem,
  loadMoreData = () => undefined,
  renderLoading = '',
  ...props
}: IAppList<D>) => {
  const { t } = useTranslation();
  const defaultGrid = React.useMemo(() => {
    return {
      xs: 1, // < 576
      sm: 2, // >= 576 AND < 768
      md: 3, // >=768 AND < 992
      lg: 4, // >=992 AND < 1200 
      xl: 6, // >= 1200 AND < 1600 
      xxl: 3, // >= 1600
    }
  }, []);

  const renderList = () => {
    return <List
      bordered={true}
      grid={grid ?? defaultGrid}
      dataSource={data}
      itemLayout={layout}
      header={renderHeader}
      footer={renderFooter}
      renderItem={renderItem}
      {...props}
    />
  }
  if (!data?.length) {
    return <div className='flex justify-center w-full'>
      {t('common.list.empty')}
    </div>
  }

  return (
    <If condition={hasLoadMore}>
      <Then>
        <InfiniteScroll
          dataLength={data?.length}
          next={loadMoreData}
          hasMore={data.length < loadMoreCount}
          loader={renderLoading}
        >
          {renderList()}
        </InfiniteScroll>
      </Then>
      <Else>
        {renderList()}
      </Else>
    </If>
  )
} 