const validationSchema = Yup.object().shape({
  firstName: Yup.string()
    .required('First name is required')
    .min(3, 'First name must be at least 3 characters long')
    .max(20, 'First name must be less than 20 characters'),
  terms: Yup.boolean()
    .oneOf([true], 'You must accept the terms and conditions'),
  group: Yup.array()
    .of(Yup.string().required('Group cannot be empty'))
    .min(1, "At least one group")
    .required("Groups is required"),
  gender: Yup.string()
    .required('Gender is required'),
  hobbies: Yup.array()
    .of(Yup.string().required('Hobby cannot be empty'))
    .min(1, "At least one hobby")
    .required("Hobbies is required"),
  phone: Yup.string()
    .required('Phone is required'),
  numberFormat: Yup.string()
    .required('numberFormat is required'),
  on: Yup.boolean().oneOf([true], 'Switch must be turned on').required('Switch is required'),
  time: Yup.string().required('Time is required'),
  date: Yup.string().required('Time is required'),
  pin: Yup.string().required('Time is required')
});

interface FormValues {
  firstName: string;
  terms?: boolean;
  group: string[];
  gender: string;
  hobbies: string[];
  phone: string;
  numberFormat: string;
  on: boolean;
  time: string;
  date: string;
  pin: string;
}

